FALLBACK = {'src/third_party/ncnn/cmakelists.txt': ''}


def digest(data):
    return hashlib.sha256(data).hexdigest()

def safe_path(root, relative):
    parts = PurePosixPath(relative).parts
    if not parts or PurePosixPath(relative).is_absolute() or any(x in (".", "..") for x in parts):
        raise RuntimeError("Unsafe relative path: " + relative)
    result = root.joinpath(*parts)
    result.resolve().relative_to(root)
    cursor = root
    for part in parts:
        cursor = cursor / part
        if cursor.is_symlink():
            raise RuntimeError("Symbolic links are not modified: " + relative)
    return result

def verify_originals(root):
    failures = []
    for relative, expected in BASELINE.items():
        target = safe_path(root, relative)
        if not target.is_file() or digest(target.read_bytes()) != expected:
            failures.append(relative)
    if failures:
        raise RuntimeError("Release verification failed: " + repr(failures[:12]))
    return len(BASELINE)

def repair(root, apply=False):
    root = root.resolve()
    if not root.is_dir():
        raise RuntimeError("Repository folder does not exist")
    restores = []
    removals = []
    errors = []
    for relative, expected in BASELINE.items():
        target = safe_path(root, relative)
        if target.exists():
            if not target.is_file() or digest(target.read_bytes()) != expected:
                errors.append("Original file was changed; not overwritten: " + relative)
            continue
        data = None
        for source_name in CANDIDATES.get(relative, []):
            source = safe_path(root, source_name)
            if source.is_file():
                value = source.read_bytes()
                if digest(value) == expected:
                    data = value
                    break
        if data is None and relative in FALLBACK:
            data = base64.b64decode(FALLBACK[relative], validate=True)
        if data is None or digest(data) != expected:
            errors.append("Cannot recover verified bytes: " + relative)
        else:
            restores.append((relative, data))
    for kind, reviewed in (("misplaced", CLEANUP), ("placeholder", MARKERS)):
        for relative, expected in reviewed.items():
            if relative in BASELINE:
                raise RuntimeError("Cleanup overlaps an original file")
            source = safe_path(root, relative)
            if source.exists():
                if not source.is_file() or digest(source.read_bytes()) != expected:
                    errors.append("Cleanup file was changed; not removed: " + relative)
                else:
                    removals.append((relative, expected, kind))
    if errors:
        raise RuntimeError("Preflight stopped before writing any files:\n" + "\n".join(errors[:20]))
    stats = {
        "original_files": len(BASELINE),
        "restore_files": len(restores),
        "remove_misplaced": sum(kind == "misplaced" for _,_,kind in removals),
        "remove_placeholders": sum(kind == "placeholder" for _,_,kind in removals),
    }
    if not apply:
        print("UPLOAD_REPAIR_DRY_RUN", stats)
        return stats
    for relative, data in restores:
        target = safe_path(root, relative)
        target.parent.mkdir(parents=True, exist_ok=True)
        with target.open("xb") as output:
            output.write(data)
    verify_originals(root)
    for relative, expected, kind in removals:
        source = safe_path(root, relative)
        if digest(source.read_bytes()) != expected:
            raise RuntimeError("File changed during repair; not removed: " + relative)
        source.unlink()
    verify_originals(root)
    print("UPLOAD_REPAIR_PASS", stats)
    return stats

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=Path("."))
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args()
    try:
        repair(args.root, apply=args.apply)
    except Exception as error:
        print("UPLOAD_REPAIR_STOPPED:", str(error))
        return 1
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
